/**
 * 合并两个不相交集合.
 * 为简明起见，我们假设 root1 和 root2 是互异的
 * 并各代表一个集合的名字.
 * root1 为集合1的根.
 * root2 为集合2的根.
 */
void DisjSets::unionSets( int root1, int root2 )
{
    s[ root2 ] = root1;
}
