```cpp
/**
 * 执行一次 find.
 * 为简单起见，再次忽略差错检验.
 * 返回包含x的集合.
 */
int DisjSets::find( int x ) const
{
    if( s[ x ] < 0 )
        return x;
    else
        return find( s[ x ] );
}
