```cpp
/**
 * 合并两个不相交集合.
 * 为简单起见，假设root1和root2是互异的
 * 并且均代表集合的名字.
 * root1 是 set 1的根.
 * root2 是 set 2的根.
 */
void DisjSets::unionSets( int root1, int root2 )
{
    if( s[ root2 ] < s[ root1 ] )  // root2 更深
        s[ root1 ] = root2;      // 使root2 为新的根
    else
    {
        if( s[ root1 ] == s[ root2 ] )
            --s[ root1 ];          // 如果相同，则更新高度
        s[ root2 ] = root1;      // 使root1 为新的根
    }
}
```

```cpp
/**
 * 利用路径压缩执行一次 find.
 * 为简单起见，再次忽略差错检验.
 * 返回包含 x 的集合.
 */
int DisjSets::find( int x )
{
    if( s[ x ] < 0 )
        return x;
    else
        return s[ x ] = find( s[ x ] );
}
